-- Fills reliability_rating/pros/cons on the 7 transmission units imported from the old
-- (legacy, flat) transmissions table -- DQ200, DQ381, DQ250, MQ200, DQ500, MQ250, MQ350 --
-- plus their deduped new fault rows (exact-text, case-insensitive, same convention as the
-- engine-fault import). Generated by scripts/fill/write-gearbox-content-migration.mjs from
-- hand-curated, Martin-approved content (see conversation) -- not a mechanical pass-through.
-- Each pros/cons item recurred (same meaning) across >= 2 of the unit's contributing old-
-- vehicle rows; car-specific categories (towing, body, 4x4, consumption) dropped regardless
-- of recurrence; capped at 5 each. family/speeds re-verified live immediately before writing.
--
-- COALESCE on content (never overwrites); each fault INSERT is itself guarded (WHERE NOT
-- EXISTS, case-insensitive) against a duplicate already on that unit. Review-only: NOT run
-- by this session. Run once, in a fresh SQL editor tab.

BEGIN;

-- Precondition: all 7 units currently NULL on reliability_rating/pros/cons.
DO $$
DECLARE non_null_n integer;
BEGIN
  SELECT count(*) INTO non_null_n FROM transmission_units
  WHERE id IN ('9e1b295a-3454-4994-aaab-aeff0ffb06dd', '87104fc9-f289-405e-8717-c8778ed406e0', 'd09ea3eb-d9c6-4434-a4c5-49cdef58c6a9', '23c93265-aeb4-4925-9896-0adad71ac22a', 'c349a00d-a7d0-4552-9d7c-9bf8a94db64a', '0eaea52c-e4ed-48cd-8ced-515892056797', '983f6f4f-cb1b-473b-b076-96d61ccb7e63') AND (reliability_rating IS NOT NULL OR pros IS NOT NULL OR cons IS NOT NULL);
  IF non_null_n <> 0 THEN
    RAISE EXCEPTION 'Expected 0 of the 7 targeted units to already have content set, found % -- aborting.', non_null_n;
  END IF;
END $$;

-- DQ200 (live: family=dct_dry, speeds=7)
UPDATE transmission_units SET
  reliability_rating = COALESCE(reliability_rating, 2),
  pros = COALESCE(pros, ARRAY['Quick, responsive shifts', 'Good fuel economy', 'Convenient in stop-and-go traffic']::text[]),
  cons = COALESCE(cons, ARRAY['Mechatronics failure is the main reliability risk', 'Dry-clutch judder in slow-moving traffic', 'Repair cost can be disproportionate to the car''s value']::text[])
WHERE id = '9e1b295a-3454-4994-aaab-aeff0ffb06dd';

-- DQ381 (live: family=dct_wet, speeds=7)
UPDATE transmission_units SET
  reliability_rating = COALESCE(reliability_rating, 4),
  pros = COALESCE(pros, ARRAY['Wet-clutch design — far more reliable than the dry-clutch DQ200', 'Quick, smooth shifts', 'Handles high torque well']::text[]),
  cons = COALESCE(cons, ARRAY['More expensive to repair than a manual gearbox', 'Occasional software updates needed for shift quality']::text[])
WHERE id = '87104fc9-f289-405e-8717-c8778ed406e0';

-- DQ250 (live: family=dct_wet, speeds=6)
UPDATE transmission_units SET
  reliability_rating = COALESCE(reliability_rating, 4),
  pros = COALESCE(pros, ARRAY['Wet-clutch design — more reliable than the dry-clutch DQ200', 'Quick, smooth shifts', 'Handles high torque well']::text[]),
  cons = COALESCE(cons, ARRAY['Mechatronics repair is costly when it fails', 'Full service history should be verified on used examples']::text[])
WHERE id = 'd09ea3eb-d9c6-4434-a4c5-49cdef58c6a9';

-- MQ200 (live: family=manual, speeds=5)
UPDATE transmission_units SET
  reliability_rating = COALESCE(reliability_rating, 5),
  pros = COALESCE(pros, ARRAY['Very robust, few failures', 'Light, easy clutch action', 'Cheap to maintain — inexpensive clutch replacement', 'Precise shift action']::text[]),
  cons = COALESCE(cons, ARRAY['Only 5 speeds — higher revs on the motorway']::text[])
WHERE id = '23c93265-aeb4-4925-9896-0adad71ac22a';

-- DQ500 (live: family=dct_wet, speeds=7)
UPDATE transmission_units SET
  reliability_rating = COALESCE(reliability_rating, 4),
  pros = COALESCE(pros, ARRAY['Most robust DSG variant, built for high torque', 'Quick, smooth shifts', 'Wet-clutch design, no DQ200 issues']::text[]),
  cons = COALESCE(cons, ARRAY['Most expensive DSG to repair if mechatronics fails']::text[])
WHERE id = 'c349a00d-a7d0-4552-9d7c-9bf8a94db64a';

-- MQ250 (live: family=manual, speeds=6)
UPDATE transmission_units SET
  reliability_rating = COALESCE(reliability_rating, 4),
  pros = COALESCE(pros, ARRAY['Proven, reliable manual gearbox', 'Lower running cost than a DSG', 'Direct, engaging shift feel']::text[]),
  cons = COALESCE(cons, ARRAY['DMF (dual-mass flywheel) is a wear item on diesel engines', 'Less convenient than an automatic in heavy traffic']::text[])
WHERE id = '0eaea52c-e4ed-48cd-8ced-515892056797';

-- MQ350 (live: family=manual, speeds=6)
UPDATE transmission_units SET
  reliability_rating = COALESCE(reliability_rating, 4),
  pros = COALESCE(pros, ARRAY['Proven, reliable manual gearbox', 'Lower running cost than a DSG', 'Direct driving control']::text[]),
  cons = COALESCE(cons, ARRAY['DMF (dual-mass flywheel) is a wear item on diesel engines']::text[])
WHERE id = '983f6f4f-cb1b-473b-b076-96d61ccb7e63';

-- Postcondition: all 7 units now have reliability_rating/pros/cons set.
DO $$
DECLARE filled_n integer;
BEGIN
  SELECT count(*) INTO filled_n FROM transmission_units
  WHERE id IN ('9e1b295a-3454-4994-aaab-aeff0ffb06dd', '87104fc9-f289-405e-8717-c8778ed406e0', 'd09ea3eb-d9c6-4434-a4c5-49cdef58c6a9', '23c93265-aeb4-4925-9896-0adad71ac22a', 'c349a00d-a7d0-4552-9d7c-9bf8a94db64a', '0eaea52c-e4ed-48cd-8ced-515892056797', '983f6f4f-cb1b-473b-b076-96d61ccb7e63') AND reliability_rating IS NOT NULL AND pros IS NOT NULL AND cons IS NOT NULL;
  IF filled_n <> 7 THEN
    RAISE EXCEPTION 'Expected all 7 units filled, found %.', filled_n;
  END IF;
END $$;

